    if (mtmp.mfrozen && !(mtmp.mfrozen = (mtmp.mfrozen - 1 >>> 0) & 127)) {
        mtmp.mcanmove = 1;
    }
    if (mtmp.mfleetim && !(mtmp.mfleetim = (mtmp.mfleetim - 1 >>> 0) & 127)) {
        mtmp.mflee = 0;
    }
