    gs.somebody_can_move = FALSE;
    await iter_mons_safe(movemon_singlemon);
    if (any_light_source()) {
        gv.vision_full_recalc = 1;   /* in case a mon moved w/ a light source */
    }
    /* reset obj bypasses after last monster has moved */
    if (svc.context.bypasses) {
        clear_bypasses();
    }
